import{describe,it,expect}from"vitest";import{festivals,months,getFestivalById,getFestivalsByMonth,getFestivalsByCity,filterFestivals}from"../../frontend/up-festival-calendar/up-festival-calendar.js";const REQUIRED_FESTIVAL_FIELDS=["id","name","month","monthIndex","city","locationCoords","duration","significance","description","rituals","highlights","icon","imageBadge","colorTheme"],MANDATORY_FESTIVAL_IDS=["dev_deepawali","lathmar_holi","ram_navami","janmashtami","ganga_mahotsav","kumbh_mela","magh_mela"];describe("UP Festival Calendar Dataset Integrity",()=>{it("contains at least 12 festivals covering all 12 calendar months",()=>{expect(festivals.length).toBeGreaterThanOrEqual(12)}),it("contains all mandatory specified UP festivals",()=>{const e=festivals.map(e=>e.id.toLowerCase());MANDATORY_FESTIVAL_IDS.forEach(t=>{expect(e,`Missing mandatory festival ${t}`).toContain(t)})}),it("every festival object contains all required fields with valid types",()=>{festivals.forEach((e,t)=>{REQUIRED_FESTIVAL_FIELDS.forEach(a=>{expect(e,`Festival at index ${t} missing field ${a}`).toHaveProperty(a),"rituals"===a||"highlights"===a?(expect(Array.isArray(e[a])).toBe(!0),expect(e[a].length).toBeGreaterThan(0)):"monthIndex"===a?(expect(typeof e.monthIndex).toBe("number"),expect(e.monthIndex).toBeGreaterThanOrEqual(1),expect(e.monthIndex).toBeLessThanOrEqual(12)):"locationCoords"===a?(expect(typeof e.locationCoords.x).toBe("number"),expect(typeof e.locationCoords.y).toBe("number")):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all festival IDs are unique",()=>{const e=festivals.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Festival Query Helpers",()=>{it("retrieves festival profile by ID or name",()=>{const e=getFestivalById("dev_deepawali");expect(e).toBeDefined(),expect(e.name).toContain("Dev Deepawali"),expect(e.city).toBe("Varanasi");const t=getFestivalById("Janmashtami");expect(t).toBeDefined(),expect(t.id).toBe("janmashtami")}),it("retrieves festivals occurring in a specific month by index or name",()=>{const e=getFestivalsByMonth(11);expect(e.length).toBeGreaterThan(0);const t=e.map(e=>e.id);expect(t).toContain("dev_deepawali");const a=getFestivalsByMonth("March");expect(a.length).toBeGreaterThan(0),expect(a[0].id).toBe("lathmar_holi")}),it("retrieves festivals celebrated in a specific city",()=>{const e=getFestivalsByCity("Prayagraj");expect(e.length).toBeGreaterThanOrEqual(2)})}),describe("Search & Filter Helpers",()=>{it("filters festivals by search query (e.g. Diyas or Barsana)",()=>{const e=filterFestivals("Diyas");expect(e.length).toBeGreaterThan(0),expect(e[0].id).toBe("dev_deepawali")}),it("filters festivals by month and city combined",()=>{const e=filterFestivals("","January","Prayagraj");expect(e.length).toBeGreaterThanOrEqual(2)}),it("returns empty array when search query matches nothing",()=>{const e=filterFestivals("NonExistentFestivalXYZ");expect(e).toEqual([])})});